build(a, snap) {
    const nums = a.nums.slice(), target = a.target, n = nums.length;
    let lo = 0, hi = n - 1;
    const view = (mid, sorted, hit) => [{
      t: "array",
      label: "nums",
      items: nums.map((v, k) => ({
        v,
        cls: k === hit ? "c" : k === mid ? "a" : k < lo || k > hi ? "d" : sorted && k >= sorted[0] && k <= sorted[1] ? "k" : "e",
      })),
      ptrs: { lo: lo >= 0 && lo < n ? lo : null, mid: mid >= 0 ? mid : null, hi: hi >= 0 && hi < n ? hi : null },
    }];
    snap(
      "开始",
      `在 [${nums.join(",")}] 里找 <b>${target}</b>。搜索范围是闭区间 [0, ${n - 1}]。`,
      view(-1),
      { at: "init", facts: [["target", target], ["区间", `[${lo}, ${hi}]`], ["lo", lo], ["hi", hi]] },
    );
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (nums[mid] === target) {
        snap(
          "计算 mid，直接命中",
          `mid = (${lo} + ${hi}) // 2 = ${mid}，nums[${mid}] = <b>${nums[mid]}</b> 正好是 target，返回 <b>${mid}</b>。`,
          view(-1, null, mid),
          { at: "found", kind: "ok", ans: mid, facts: [["target", target], ["mid", `${mid} (值 ${nums[mid]})`], ["lo", lo], ["hi", hi]] },
        );
        return;
      }
      if (nums[lo] <= nums[mid]) {
        const inL = nums[lo] <= target && target < nums[mid];
        snap(
          "计算 mid 并判断哪半有序",
          `mid = (${lo} + ${hi}) // 2 = ${mid}（nums[mid] = ${nums[mid]}）。因为 nums[lo] (${nums[lo]}) ≤ nums[mid] (${nums[mid]})，左半 [${lo}..${mid}] 是升序的，检查 ${target} 是否在 [${nums[lo]}, ${nums[mid]}) 内。`,
          view(mid, [lo, mid]),
          { at: "left", facts: [["target", target], ["mid", `${mid} (值 ${nums[mid]})`], ["有序半边", `[${lo}, ${mid}]`], ["lo", lo], ["hi", hi]] },
        );
        const prevLo = lo, prevHi = hi, prevRange = `[${lo}, ${hi}]`;
        if (inL) {
          hi = mid - 1;
          snap(
            "排除右半，收缩区间",
            `${target} 在 [${nums[lo]}, ${nums[mid]}) 里，答案一定在左半！排除 [${mid}..${prevHi}]，hi 左移到 ${hi}。`,
            view(-1),
            { at: "left", facts: [["target", target], ["区间", `[${lo}, ${hi}]`, prevRange], ["lo", lo], ["hi", hi, prevHi]] },
          );
        } else {
          lo = mid + 1;
          snap(
            "排除左半，收缩区间",
            `${target} 不在 [${nums[prevLo]}, ${nums[mid]}) 里，左半有序段可以全部排除！排除 [${prevLo}..${mid}]，lo 右移到 ${lo}。`,
            view(-1),
            { at: "left", facts: [["target", target], ["区间", `[${lo}, ${hi}]`, prevRange], ["lo", lo, prevLo], ["hi", hi]] },
          );
        }
      } else {
        const inR = nums[mid] < target && target <= nums[hi];
        snap(
          "计算 mid 并判断哪半有序",
          `mid = (${lo} + ${hi}) // 2 = ${mid}（nums[mid] = ${nums[mid]}）。因为 nums[lo] (${nums[lo]}) &gt; nums[mid] (${nums[mid]})，断点在左边，右半 [${mid}..${hi}] 是升序的，检查 ${target} 是否在 (${nums[mid]}, ${nums[hi]}] 内。`,
          view(mid, [mid, hi]),
          { at: "right", facts: [["target", target], ["mid", `${mid} (值 ${nums[mid]})`], ["有序半边", `[${mid}, ${hi}]`], ["lo", lo], ["hi", hi]] },
        );
        const prevLo = lo, prevHi = hi, prevRange = `[${lo}, ${hi}]`;
        if (inR) {
          lo = mid + 1;
          snap(
            "排除左半，收缩区间",
            `${target} 在 (${nums[mid]}, ${nums[prevHi]}] 里，答案一定在右半！排除 [${prevLo}..${mid}]，lo 右移到 ${lo}。`,
            view(-1),
            { at: "right", facts: [["target", target], ["区间", `[${lo}, ${hi}]`, prevRange], ["lo", lo, prevLo], ["hi", hi]] },
          );
        } else {
          hi = mid - 1;
          snap(
            "排除右半，收缩区间",
            `${target} 不在 (${nums[mid]}, ${nums[prevHi]}] 里，右半有序段可以全部排除！排除 [${mid}..${prevHi}]，hi 左移到 ${hi}。`,
            view(-1),
            { at: "right", facts: [["target", target], ["区间", `[${lo}, ${hi}]`, prevRange], ["lo", lo], ["hi", hi, prevHi]] },
          );
        }
      }
    }
    snap(
      "没找到",
      `lo = ${lo} &gt; hi = ${hi}，区间空了，数组里没有 ${target}，返回 <b>-1</b>。`,
      view(-1),
      { at: "miss", kind: "warn", ans: -1, facts: [["target", target], ["lo", lo], ["hi", hi], ["结果", -1]] },
    );
  }

